"use client";

import { useEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { clearOperatingReview, illustrativeActionImpact, linkOperatingActionExpense, normalizeOperatingPlanBody, OPERATING_ACTIONS, OPERATING_CADENCES, OPERATING_CATEGORIES, operatingExpenseAmount, operatingExpenseProposal, operatingExpenseTotal, operatingLabel, operatingMoney, operatingNumber, proposeExpense, proposeExpenseUnits, type OperatingAction, type OperatingCadence, type OperatingCostBasis, type OperatingEvaluation, type OperatingExpense, type OperatingPlanBody } from "@/lib/operatingPlan";
import styles from "./OperatingPlanForm.module.css";
import { ReleasedCashFlowAllocation } from "./ReleasedCashFlowAllocation";
import type { ReleasedCashFlowEvaluation } from "@/lib/operatingPlan";
import { metricAmountLabel } from "@/lib/financialMetrics";
import { NoiGovernanceSummary } from "@/components/file/cockpit/NoiGovernanceSummary";
import type { OperatingSuggestionClient } from "@/lib/operatingSuggestions";
import type { OperatingGoalRead } from "@/lib/operatingGoal";
import { type OperatingDraftSaveStatus, type OperatingCalculationStatus } from "@/lib/operatingPlanFeedback";
import type { OperatingConfigurationRequest } from "./OperatingChangeConfiguration";
import { OperatingPlanGuide } from "./OperatingPlanGuide";
import { OperatingAmountInput } from "./OperatingAmountInput";
import { OperatingUnitHeader, OperatingUnitReadout, OperatingVolumeBehavior } from "./OperatingUnitPlanning";
import { invalidateOperatingUnitVolume, normalizeOperatingUnitAction, operatingSourceRevenue, operatingUnitsUsed, operatingUnitAction, proposeOperatingUnitVolume } from "@/lib/operatingUnitPlanning";
import { StableOperatingPreview } from "./StableOperatingPreview";
import { addOperatingCandidate, draftOperatingSourceCosts, operatingRecurringSubtotal, updateOperatingExpense, type OperatingGuidance, type OperatingGuidanceEvidence } from "@/lib/operatingGuidance";

export type OperatingSource = { file_id: string; file_name: string };
type Tab = "expenses" | "actions" | "impact";
const display = (value: unknown) => value == null ? "" : String(value);
const uid = () => crypto.randomUUID();

function WrappedCell({ label, value, disabled, placeholder, onChange }: { label: string; value: string; disabled?: boolean; placeholder: string; onChange: (value: string) => void }) {
  const ref = useRef<HTMLTextAreaElement>(null);
  useEffect(() => { const input = ref.current; if (input) { input.style.height = "auto"; input.style.height = `${input.scrollHeight}px`; } }, [value]);
  return <textarea ref={ref} className={styles.cellText} aria-label={label} rows={2} value={value} disabled={disabled} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} />;
}

/** Staff and clients edit the same versioned body; approvals belong to staff review. */
export function OperatingPlanForm({ value: rawValue, onChange, disabled = false, sources = [], onPreviewSource, evaluation, releasedCashFlow, evaluating, reviewControls, reportControls, staff = false, processingReferences, onProcessingReference, guidance, evidence, guidedDefault = false, onGuidedModeChange, guidedStepRequest, sourceDraftRequest = 0, onOpenSources, sourceTools, sourceMessage, onConfirmSource, onSaveVersion, saveVersionDisabled, saveVersionBusy, saveVersionLabel = "Save version", goal, goalControls, suggestionClient, saveStatus, calculationStatus }: {
  reportControls?: ReactNode;
  saveStatus?: OperatingDraftSaveStatus; calculationStatus?: OperatingCalculationStatus;
  suggestionClient?: OperatingSuggestionClient;
  goal?: OperatingGoalRead | null; goalControls?: ReactNode;
  value: OperatingPlanBody; onChange: (body: OperatingPlanBody) => void; disabled?: boolean;
  sources?: OperatingSource[]; onPreviewSource?: (id: string) => void;
  evaluation?: OperatingEvaluation | null; evaluating?: boolean; reviewControls?: ReactNode; staff?: boolean;
  releasedCashFlow?: ReleasedCashFlowEvaluation | null;
  processingReferences?: { sources: Array<{ key: string; label: string }>; offers: Array<{ id: string; label: string }> };
  onProcessingReference?: (row: OperatingAction, sourceKey: string, offerId: string) => void;
  guidance?: OperatingGuidance | null; evidence?: OperatingGuidanceEvidence | null; guidedDefault?: boolean;
  onGuidedModeChange?: (guided: boolean) => void; guidedStepRequest?: { index: number; key: number } | null;
  sourceDraftRequest?: number; onOpenSources?: () => void; sourceTools?: ReactNode; sourceMessage?: ReactNode; onConfirmSource?: () => void; onSaveVersion?: () => void | Promise<void>; saveVersionDisabled?: boolean; saveVersionBusy?: boolean; saveVersionLabel?: string;
}) {
  const value = normalizeOperatingPlanBody(rawValue);
  const lastEvaluation = useRef<OperatingEvaluation | null>(evaluation ?? null);
  const sourceKey = JSON.stringify(guidance?.reporting || {});
  const lastReadySource = useRef(sourceKey);
  const lastBridgeSnapshotSource = useRef(releasedCashFlow?.source_fingerprint ?? null);
  if (evaluation && !evaluating) { lastEvaluation.current = evaluation; lastReadySource.current = sourceKey; lastBridgeSnapshotSource.current = releasedCashFlow?.source_fingerprint ?? null; }
  const previousBridge = lastReadySource.current === sourceKey ? lastEvaluation.current?.cash_bridge : null;
  const loanSnapshotChanged = (releasedCashFlow?.source_fingerprint ?? null) !== lastBridgeSnapshotSource.current && (releasedCashFlow?.source_fingerprint ?? null) !== previousBridge?.source_fingerprint;
  const savedBridge = evaluation?.cash_bridge ?? (loanSnapshotChanged ? null : previousBridge);
  const pricingSourceRevenue = lastReadySource.current === sourceKey && guidance?.reporting.source_file_id ? operatingSourceRevenue(value, lastEvaluation.current, guidance) : null;
  const [tab, setTab] = useState<Tab>("expenses");
  const [selected, setSelected] = useState<{ collection: "expenses" | "adjustments"; id: string } | null>(null);
  const [showExcluded, setShowExcluded] = useState(false);
  const guided = true;
  const [plannerStep, setPlannerStep] = useState(0);
  const [growthRequest, setGrowthRequest] = useState(0);
  const [configurationRequest, setConfigurationRequest] = useState<OperatingConfigurationRequest>();
  const [allocationFocusRequest, setAllocationFocusRequest] = useState<{ key: number; allocationId?: string; field?: string }>();
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const formElement = useRef<HTMLDivElement>(null);
  const unitHeader = useRef<HTMLElement>(null);
  const unitProposalHeader = useRef<HTMLElement>(null);
  const [unitFix, setUnitFix] = useState<string | null>(null);
  const reviewExpense = (id: string, field?: string) => { setPlannerStep(2); setAdvancedOpen(false); requestAnimationFrame(() => {
    const currentDetails = formElement.current?.querySelector<HTMLDetailsElement>("[data-operating-current-details]"); if (currentDetails) currentDetails.open = true;
    const group = [...(formElement.current?.querySelectorAll<HTMLElement>("[data-operating-source-group]") || [])].find(node => value.expenses?.some(row => row.id === id && row.source_group_key === node.dataset.operatingSourceGroup));
    const card = [...(formElement.current?.querySelectorAll<HTMLElement>("[aria-label]") || [])].find(node => node.getAttribute("aria-label") === `Current item ${id}`);
    const label = field?.includes("current_units") ? `Quantity per period ${id}` : field?.includes("current_unit_cost") ? `Cost per unit ${id}` : field?.includes("current_fixed_amount") ? `Fixed portion ${id}` : field?.includes("current_amount") ? `Current total ${id}` : field?.endsWith(".label") ? `Current expense ${id} name` : undefined;
    const derivedRepair = field?.includes("reconcile_current_amount") ? [...(card?.querySelectorAll<HTMLButtonElement>("button") || [])].find(node => node.textContent?.trim() === "Confirm derived current total") : null;
    const currentHost = card || group;
    const target = derivedRepair || (label ? [...(card?.querySelectorAll<HTMLElement>("[aria-label]") || [])].find(node => node.getAttribute("aria-label") === label) : currentHost?.querySelector<HTMLElement>('input[aria-invalid="true"],select[aria-invalid="true"],input:not(:disabled),select:not(:disabled)'));
    const details = target?.closest("details"); if (details) details.open = true;
    const node = target || group || card; if (node && !node.matches("input,select,textarea,button,a")) node.tabIndex = -1; node?.focus({ preventScroll: true }); node?.scrollIntoView({ block: "center", behavior: "smooth" });
  }); };
  const fixFeedback = (actionId?: string, field?: string) => {
    const action = value.adjustments?.find(row => row.id === actionId || field?.includes(row.id));
    const expense = value.expenses?.find(row => field?.includes(row.id));
    if (field?.startsWith("released_cash_flow")) { setPlannerStep(2); setAdvancedOpen(false); setAllocationFocusRequest({ key: Date.now(), allocationId: value.released_cash_flow?.allocations.find(row => field.includes(row.id))?.id, field }); return; }

    if (/^baseline\.|^noi_|source_comparability/.test(field || "")) { setPlannerStep(0); setAdvancedOpen(false); return; }
    if (/annual_debt_service|debt_service_currency/.test(field || "")) { setPlannerStep(3); return; }
    if (field?.includes("projection_start")) { setAdvancedOpen(false); setPlannerStep(2); requestAnimationFrame(() => { const target = formElement.current?.querySelector<HTMLElement>('[aria-label="Plan changes start"]'); const details = target?.closest("details"); if (details) details.open = true; target?.focus(); }); return; }
    if (action?.expense_row_id && ["expense_reduction", "expense_increase", "marketing_investment"].includes(action.kind || "") && ["current_amount", "current_units_per_period", "current_unit_cost", "current_fixed_amount", "unit_label", "cadence"].includes(field?.split(".").at(-1) || "")) { reviewExpense(action.expense_row_id, field); return; }
    if (field?.includes("source") && !/source_note|source_file_ids/.test(field) || expense) { if (expense || action?.expense_row_id) reviewExpense(expense?.id || action!.expense_row_id!, field); else { setPlannerStep(0); setAdvancedOpen(false); } return; }
    if (field?.includes("historical_revenue_annual") || field?.includes("historical_units_annual")) { fixUnitField(field); return; }
    if (!action) { setPlannerStep(field?.includes("historical") ? 1 : 2); return; }
    if (action.kind === "unit_volume" && /unit_change_value|proposed_units|unit_change_mode/.test(field || "")) { setPlannerStep(2); setConfigurationRequest({ key: Date.now(), actionId: action.id, field }); return; }
    if (action.kind === "processing_cost_change" && /processing_|merchant_/.test(field || "")) { fixUnitField(`adjustments.${action.id}.${field?.split(".").at(-1)}`); return; }
    setPlannerStep(2); setAdvancedOpen(false);
    setConfigurationRequest({ key: Date.now(), actionId: action.id, field }); return;
  };
  const focusUnits = () => { setPlannerStep(2); const action = operatingUnitAction(value); if (action) setConfigurationRequest({ key: Date.now(), actionId: action.id, field: "unit_change_value" }); };
  const fixUnitField = (path: string) => {
    const primaryHeader = path.includes("historical_") || path === "unit_label" || path.includes("period_start") || path.includes("period_end");
    setAdvancedOpen(!primaryHeader);
    if (primaryHeader) setPlannerStep(path.includes("period_start") || path.includes("period_end") ? 0 : 2);
    const row = value.expenses?.find(item => path.includes(item.id));
    const action = value.adjustments?.find(item => path.includes(item.id));
    setTab(action ? "actions" : "expenses");
    if (row) setSelected({ collection: "expenses", id: row.id });
    else if (action) setSelected({ collection: "adjustments", id: action.id });
    setUnitFix(path);
  };
  useEffect(() => {
    if (!unitFix) return;
    const row = value.expenses?.find(item => unitFix.includes(item.id));
    const action = value.adjustments?.find(item => unitFix.includes(item.id));
    const processingKey = unitFix.split(".").at(-1) || "";
    const processingLabel = action?.kind === "processing_cost_change" ? ({ processing_volume: "Card volume per period", processing_transaction_count: "Transactions per period", current_processing_rate_pct: `Current rate percent for ${action.label || "action"}`, proposed_processing_rate_pct: `Proposed rate percent for ${action.label || "action"}`, current_processing_rate_basis: "current processing rate basis", proposed_processing_rate_basis: "proposed processing rate basis", current_processing_fixed_fee: "current processing fixed fee", proposed_processing_fixed_fee: "proposed processing fixed fee", current_processing_per_transaction_fee: "current per transaction fee", proposed_processing_per_transaction_fee: "proposed per transaction fee", merchant_source_key: "Current processing statement", merchant_offer_id: "Proposed processing quote" } as Record<string, string>)[processingKey] : undefined;
    const label = processingLabel || (row ? unitFix.includes("current_fixed_amount") ? row.cost_basis === "per_unit" ? "Current expense fixed cost" : `Fixed volume cost for ${row.id}` : unitFix.includes("volume_behavior") ? `Volume behavior for ${row.id}` : unitFix.includes("recurring_annual_amount") ? row.cost_basis === "per_unit" ? "Current expense quantity" : `Current amount for ${row.label || "expense"}` : "Expense details"
      : action ? unitFix.includes("processing_volume") ? "Card volume per period" : unitFix.includes("unit_change_value") || unitFix.includes("proposed_units") || unitFix.includes("proposed_revenue") ? "Planned annual unit change" : "Earnings action details"
      : unitFix.includes("revenue") ? "Historical annual business revenue" : unitFix.includes("unit_label") ? "Business unit definition" : unitFix.includes("period") ? "Operating reporting period start" : unitFix.includes("expenses_or_no_expenses") ? "Operating expenses table. Scroll across columns or down rows." : "Historical annual business units");
    const target = [...(formElement.current?.querySelectorAll<HTMLElement>("[aria-label]") ?? [])].find(item => item.getAttribute("aria-label") === label);
    if (target) { let parent = target.parentElement; while (parent && formElement.current?.contains(parent)) { if (parent instanceof HTMLDetailsElement) parent.open = true; parent = parent.parentElement; } if (!target.matches("input,select,textarea,button")) target.tabIndex = -1; target.focus({ preventScroll: true }); target.scrollIntoView({ block: "center", behavior: "smooth" }); }
    setUnitFix(null);
  }, [unitFix, value.expenses, value.adjustments]);
  const unitsUsed = operatingUnitsUsed(value);
  const unitEvaluation = !evaluating ? evaluation?.unit_economics : null;
  const lastSourceDraft = useRef(0);
  useEffect(() => {
    if (!sourceDraftRequest || lastSourceDraft.current === sourceDraftRequest) return;
    lastSourceDraft.current = sourceDraftRequest; setPlannerStep(1); setAdvancedOpen(false); setTab("expenses"); setSelected(null);
    const frame = requestAnimationFrame(() => { const heading = formElement.current?.querySelector<HTMLElement>("[data-operating-step-heading]"); heading?.focus({ preventScroll: true }); formElement.current?.querySelector<HTMLElement>('[aria-label="Guided operating expenses and earnings plan"]')?.scrollIntoView({ block: "start", behavior: "smooth" }); });
    return () => cancelAnimationFrame(frame);
  }, [sourceDraftRequest]);
  const expenses = value.expenses ?? []; const actions = value.adjustments ?? [];
  const totals = operatingExpenseTotal(expenses); const currency = value.currency || "USD";
  const activeExpenses = expenses.filter(row => !row.excluded && !row.duplicate_of);
  const recurringSubtotal = operatingRecurringSubtotal(expenses);
  const noCostsConfirmed = !activeExpenses.length && value.no_operating_expenses_confirmed === true;
  const recurringAnnual = noCostsConfirmed ? 0 : recurringSubtotal.annual;
  const money = (number: number | null | undefined) => operatingMoney(number, currency);
  const active = <T extends { excluded?: boolean; duplicate_of?: string | null }>(rows: T[]) => rows.filter((row) => showExcluded || !row.excluded && !row.duplicate_of);
  const change = (patch: Partial<OperatingPlanBody>) => onChange({ ...value, schema_version: "operating-plan-v1", ...patch });
  const changeExpense = (id: string, patch: Partial<OperatingExpense>) => onChange(invalidateOperatingUnitVolume(updateOperatingExpense(value, id, patch)));
  const changeAction = (id: string, patch: Partial<OperatingAction>) => change({ adjustments: actions.map((row) => {
    if (row.id !== id) return row;
    const next = normalizeOperatingUnitAction({ ...row, ...patch });
    if (["expense_reduction", "expense_increase"].includes(next.kind ?? "") && Object.keys(patch).some((key) => /^(current|proposed)_(amount|units_per_period|unit_cost|fixed_amount)$/.test(key))) {
      const before = operatingExpenseAmount(next); const after = operatingExpenseAmount(next, true);
      if (before != null && after != null) next.kind = after > before ? "expense_increase" : "expense_reduction";
    }
    return clearOperatingReview(next);
  }) });
  const focusedExpense = selected?.collection === "expenses" ? expenses.find((row) => row.id === selected.id) : null;
  const focusedExpenseAction = focusedExpense ? operatingExpenseProposal(value, focusedExpense.id) : null;
  const focusedAction = selected?.collection === "adjustments" ? actions.find((row) => row.id === selected.id) : null;
  const keyMove = (event: KeyboardEvent<HTMLTableElement>) => {
    if (!event.altKey || !["ArrowUp", "ArrowDown"].includes(event.key)) return;
    const element = event.target as HTMLElement; const cell = element.closest("td"); const row = cell?.parentElement;
    const next = event.key === "ArrowDown" ? row?.nextElementSibling : row?.previousElementSibling;
    const index = cell ? [...cell.parentElement!.children].indexOf(cell) : -1;
    const input = next?.children[index]?.querySelector<HTMLElement>("input,textarea,select,button");
    if (input) { event.preventDefault(); input.focus(); }
  };
  const evidenceLinks = (ids: string[] = []) => ids.length ? <button type="button" className={styles.link} onClick={() => {
    if (ids.length === 1 && onPreviewSource) onPreviewSource(ids[0]);
    else setSelected({ collection: tab === "expenses" ? "expenses" : "adjustments", id: tab === "expenses" ? expenses.find((row) => row.source_file_ids === ids)?.id ?? "" : actions.find((row) => row.source_file_ids === ids)?.id ?? "" });
  }}>{ids.length} file{ids.length === 1 ? "" : "s"}</button> : <span className={styles.muted}>No files</span>;
  const rowTools = (collection: "expenses" | "adjustments", row: OperatingExpense | OperatingAction) => <div className={styles.tools}>
    <button type="button" onClick={() => setSelected({ collection, id: row.id })} aria-label={`Details for ${row.label || "unnamed row"}`}>Details</button>
    {!disabled ? <button type="button" title={row.excluded ? "Restore this row" : "Remove from plan; keep for history"} aria-label={`${row.excluded ? "Restore" : "Remove"} ${row.label || "row"}`} onClick={() => collection === "expenses" ? changeExpense(row.id, { excluded: !row.excluded, duplicate_of: null }) : changeAction(row.id, { excluded: !row.excluded, duplicate_of: null })}>{row.excluded ? "Restore" : "×"}</button> : null}
  </div>;
  const number = (label: string, amount: unknown, commit: (text: string) => void, locked = false) => <OperatingAmountInput label={label} value={amount} onCommit={commit} disabled={disabled || locked} />;
  const cadence = (label: string, amount: OperatingCadence | undefined, commit: (text: OperatingCadence) => void) => <select aria-label={label} value={amount ?? "monthly"} disabled={disabled} onChange={(event) => commit(event.target.value as OperatingCadence)}>{OPERATING_CADENCES.map(([key, title]) => <option key={key} value={key}>{title}</option>)}</select>;
  const actionResult = (row: OperatingAction) => evaluation?.actions.find((result) => result.id === row.id);
  const filePicker = (row: OperatingExpense | OperatingAction, commit: (ids: string[]) => void) => <div className={styles.sources}>
    <span>Supporting files</span>
    {sources.length ? <select multiple aria-label={`Supporting files for ${row.label || "row"}`} disabled={disabled} value={row.source_file_ids ?? []} onChange={(event) => commit([...event.target.selectedOptions].map((option) => option.value))}>{sources.map((file) => <option key={file.file_id} value={file.file_id}>{file.file_name}</option>)}</select> : <small>Files can be attached by your team. Describe the supporting evidence below.</small>}
    {(row.source_file_ids ?? []).map((id) => <button key={id} type="button" className={styles.link} onClick={() => onPreviewSource?.(id)} disabled={!onPreviewSource}>{sources.find((file) => file.file_id === id)?.file_name ?? "Linked supporting file"}</button>)}
  </div>;
  return <div ref={formElement} className={styles.plan}>
    <OperatingPlanGuide reportControls={reportControls} configurationRequest={configurationRequest} growthRequest={growthRequest} saveStatus={saveStatus} calculationStatus={calculationStatus} onFixFeedback={fixFeedback} onReviewExpense={reviewExpense} suggestionClient={suggestionClient} goal={goal} goalControls={goalControls} stepIndex={plannerStep} onStepChange={setPlannerStep} sourceAnnualRevenue={pricingSourceRevenue} onReviewRevenue={() => fixUnitField("historical_revenue_annual")} unitProposal={operatingUnitAction(value) ? <OperatingUnitHeader section="proposal" value={value} onChange={onChange} disabled={disabled} evaluation={evaluation} evaluating={evaluating} headerRef={unitProposalHeader} onFix={fixUnitField} onEditReporting={() => fixUnitField("period_start")} /> : null} onAddUnitPlan={() => { const next = proposeOperatingUnitVolume(value, {}, uid); onChange(next); const action = operatingUnitAction(next); if (action) setConfigurationRequest({ key: Date.now(), actionId: action.id, field: "unit_change_value" }); }} sourceTools={sourceTools} sourceMessage={sourceMessage} onConfirmSource={onConfirmSource ?? (() => { if (guidance) { const result = draftOperatingSourceCosts(value, guidance, uid); if (result.body !== value) onChange(result.body); } })} onSaveVersion={onSaveVersion} saveVersionDisabled={saveVersionDisabled} saveVersionBusy={saveVersionBusy} saveVersionLabel={saveVersionLabel} unitControls={<OperatingUnitHeader section="baseline" value={value} onChange={onChange} disabled={disabled} evaluation={evaluation} evaluating={evaluating} headerRef={unitHeader} onFix={fixUnitField} onEditReporting={() => fixUnitField("period_start")} />} fundingSummary={<ReleasedCashFlowAllocation focusRequest={allocationFocusRequest} onPlanGrowth={() => { setPlannerStep(2); setGrowthRequest(key => key + 1); }} onReviewTarget={(expenseId, actionId) => { if (!actionId) { if (expenseId) reviewExpense(expenseId); return; } const read = evaluation?.draft_feedback?.actions.find(row => row.action_id === actionId); fixFeedback(actionId, read?.math_missing[0] || read?.qualification_missing[0] || read?.source_issues[0] || read?.fix_fields?.[0]); }} working={evaluation?.draft_feedback?.summary.working} bridge={savedBridge} value={value} onChange={onChange} source={evaluation?.released_cash_flow ?? releasedCashFlow} disabled={disabled || plannerStep < 2} evaluating={evaluating} />} value={value} onChange={onChange} guidance={guidance} evidence={evidence} evaluation={evaluation} layoutEvaluation={lastReadySource.current === sourceKey ? lastEvaluation.current : null} evaluating={evaluating} disabled={disabled} onPreviewSource={onPreviewSource} reviewControls={reviewControls} stepRequest={guidedStepRequest} onAdvancedAction={id => fixUnitField(`adjustments.${id}.processing_volume`)} onEditUnits={focusUnits} detailedImpact={<StableOperatingPreview pending={Boolean(evaluating || !evaluation)}><OperatingPlanImpact evaluation={evaluation} evaluating={evaluating} currency={currency} client={!staff} /></StableOperatingPreview>} />
    <details open={advancedOpen} onToggle={event => setAdvancedOpen(event.currentTarget.open)}><summary>Advanced tables</summary>
    <div className={styles.identity}>
      <label>Business<input value={value.business_name ?? ""} disabled={disabled} onChange={(event) => change({ business_name: event.target.value })} /></label>
      <label>Period start<input aria-label="Operating reporting period start" type="date" value={value.period_start ?? ""} disabled={disabled} onChange={(event) => change({ period_start: event.target.value })} /></label>
      <label>Period end<input type="date" value={value.period_end ?? ""} disabled={disabled} onChange={(event) => change({ period_end: event.target.value })} /></label>
      <label>Currency<input maxLength={3} value={currency} disabled={disabled} onChange={(event) => change({ currency: event.target.value.toUpperCase() })} /></label>
      <label>Basis<select value={value.basis ?? "unknown"} disabled={disabled} onChange={(event) => change({ basis: event.target.value as OperatingPlanBody["basis"] })}><option value="unknown">Unconfirmed</option><option value="cash">Cash</option><option value="accrual">Accrual</option></select></label>
      <label>Projection starts<input aria-label="Projection starts" type="date" value={value.projection_start ?? ""} disabled={disabled} onChange={(event) => change({ projection_start: event.target.value || null })} /></label>
    </div>
    <div className={styles.toolbar}>
      <div role="tablist" aria-label="Operating plan views" className={styles.tabs}>{([["expenses", "Operating expenses"], ["actions", "Earnings actions"], ["impact", "Before and after"]] as Array<[Tab, string]>).map(([id, label]) => <button key={id} type="button" role="tab" aria-selected={tab === id} data-operating-section={label} onClick={() => { setTab(id); setSelected(null); }}>{label}</button>)}</div>
      {tab !== "impact" ? <label className={styles.check}><input type="checkbox" checked={showExcluded} onChange={(event) => setShowExcluded(event.target.checked)} />Show removed rows</label> : null}
    </div>
    {tab === "expenses" ? <>
      {unitsUsed ? <details><summary>Cost per business unit by category and source group</summary><StableOperatingPreview pending={Boolean(evaluating || !evaluation)}>{[...(evaluation?.unit_economics?.categories ?? lastEvaluation.current?.unit_economics?.categories ?? []), ...(evaluation?.unit_economics?.expense_groups ?? lastEvaluation.current?.unit_economics?.expense_groups ?? [])].map((group, index) => <OperatingUnitReadout key={`${index}:${group.key}`} label={group.label} value={[...(unitEvaluation?.categories ?? []), ...(unitEvaluation?.expense_groups ?? [])].find(item => item.key === group.key)} unitLabel={value.unit_label} currency={value.currency} pending={Boolean(evaluating || !evaluation)} />)}</StableOperatingPreview></details> : null}
      <div className={styles.toolbar}><p className={styles.muted}>Disclose current costs. Proposed amounts create earnings actions for review. Blank means unknown. Use Tab across cells; Alt + ↑ / ↓ moves between rows.</p>{!disabled ? <button type="button" onClick={() => { const id = uid(); onChange(addOperatingCandidate(value, { category: "other", label: "", current_amount: null, cadence: "monthly", source_file_ids: [] }, id)); setSelected({ collection: "expenses", id }); }}>+ Add expense</button> : null}</div>
      <div className={styles.scroll} tabIndex={0} aria-label="Operating expenses table. Scroll across columns or down rows."><table onKeyDown={keyMove}>
        <thead><tr><th>Expense / item</th><th>Category</th><th>Cost basis</th><th>Current amount</th><th>Proposed amount</th><th>Per</th><th>Annual earnings change</th><th>Evidence</th><th>Review</th><th>Actions</th></tr></thead>
        <tbody>{active(expenses).map((row) => { const linked = operatingExpenseProposal(value, row.id); const result = linked ? actionResult(linked) : null; return <tr key={row.id} className={row.excluded || row.duplicate_of ? styles.excluded : undefined}>
          <td><WrappedCell label="Expense name" value={row.label ?? ""} disabled={disabled || row.excluded} placeholder="Rent, payroll, supplies…" onChange={(text) => changeExpense(row.id, { label: text })} /></td>
          <td><select aria-label={`Category for ${row.label || "expense"}`} value={row.category ?? "other"} disabled={disabled || row.excluded} onChange={(event) => changeExpense(row.id, { category: event.target.value })}>{OPERATING_CATEGORIES.map((key) => <option key={key} value={key}>{operatingLabel(key)}</option>)}</select></td>
          <td><select aria-label={`Cost basis for ${row.label || "expense"}`} value={row.cost_basis ?? "total"} disabled={disabled || row.excluded} onChange={(event) => { changeExpense(row.id, { cost_basis: event.target.value as OperatingCostBasis }); if (event.target.value === "per_unit") setSelected({ collection: "expenses", id: row.id }); }}><option value="total">Period total</option><option value="per_unit">Quantity × unit cost + fixed</option></select></td>
          <td>{unitsUsed ? <OperatingUnitReadout value={unitEvaluation?.rows.find(item => item.id === row.id)} unitLabel={value.unit_label} currency={value.currency} pending={Boolean(evaluating || !evaluation)} label={row.label || row.id} /> : null}{row.cost_basis === "per_unit" ? <><strong>{money(operatingExpenseAmount(row))}</strong><small>{display(row.current_units_per_period) || "?"} {row.unit_label || "units"} × {money(operatingNumber(row.current_unit_cost))} + {money(operatingNumber(row.current_fixed_amount))} fixed</small></> : number(`Current amount for ${row.label || "expense"}`, row.current_amount, (text) => changeExpense(row.id, { current_amount: text }))}</td>
          <td>{row.cost_basis === "per_unit" ? <><strong>{linked ? money(operatingExpenseAmount(linked, true)) : "—"}</strong><button type="button" className={styles.link} onClick={() => setSelected({ collection: "expenses", id: row.id })}>Edit unit costs</button></> : number(`Proposed amount for ${row.label || "expense"}`, linked?.proposed_amount, (text) => onChange(proposeExpense(value, row.id, text, uid)))}</td>
          <td>{cadence(`Frequency for ${row.label || "expense"}`, row.cadence, (text) => changeExpense(row.id, { cadence: text }))}</td>
          <td className={styles.amount}>{linked ? money(result ? result.net_annual_impact : illustrativeActionImpact(linked)) : "—"}</td><td>{evidenceLinks(row.source_file_ids)}</td><td>{linked ? operatingLabel(result?.review_state ?? linked.status ?? "proposed") : "Disclosure"}</td><td>{rowTools("expenses", row)}</td>
        </tr>; })}{!active(expenses).length ? <tr><td colSpan={10} className={styles.empty}>{staff ? <>No costs drafted yet. Use Draft from tax/P&amp;L above, or add an expense manually.{onOpenSources ? <button type="button" onClick={() => { setPlannerStep(0); setAdvancedOpen(false); requestAnimationFrame(() => onOpenSources?.()); }}>Go to source costs</button> : null}</> : "No operating expenses entered. Add a line or confirm there are none."}</td></tr> : null}</tbody>
        <tfoot><tr><th>{!activeExpenses.length && !noCostsConfirmed ? "No costs drafted yet" : recurringSubtotal.incomplete ? "Incomplete known recurring subtotal" : "Current disclosed totals"}</th><td colSpan={3}>{recurringAnnual == null ? "Unknown" : money(recurringAnnual / 12)} / month</td><td colSpan={2}>{recurringAnnual == null ? "Unknown" : money(recurringAnnual)} / year</td><td colSpan={4}>{totals.missing ? `${totals.missing} unknown amount(s) · ` : ""}{!activeExpenses.length && !noCostsConfirmed ? "Unknown" : money(totals.oneTime)} one time</td></tr></tfoot>
      </table></div>
      {!expenses.some((row) => !row.excluded && !row.duplicate_of) ? <label className={styles.check}><input type="checkbox" checked={value.no_operating_expenses_confirmed ?? false} disabled={disabled} onChange={(event) => change({ no_operating_expenses_confirmed: event.target.checked })} />The business has no operating expenses for this period.</label> : null}
    </> : tab === "actions" ? <>
      <div className={styles.toolbar}><p className={styles.muted}>Prices, product costs and operating costs stay separate. Improvements require evidence, timing and staff reconciliation to the earnings baseline.</p>{!disabled ? <button type="button" onClick={() => { const id = uid(); change({ adjustments: [...actions, { id, kind: "expense_reduction", label: "", cadence: "monthly", status: "proposed", implementation_cost: null, implementation_cost_cadence: "one_time", source_file_ids: [] }] }); setSelected({ collection: "adjustments", id }); }}>+ Add action</button> : null}</div>
      <div className={styles.scroll} tabIndex={0} aria-label="Earnings actions table. Scroll across columns or down rows."><table onKeyDown={keyMove}>
        <thead><tr><th>Action / explanation</th><th>Change type</th><th>Current</th><th>Proposed</th><th>Per</th><th>Annual earnings change</th><th>Evidence</th><th>Review</th><th>Actions</th></tr></thead>
        <tbody>{active(actions).map((row) => { const result = actionResult(row); const unitPrice = row.kind === "price_change"; const unitCost = row.kind === "product_cost_change"; const processing = row.kind === "processing_cost_change"; const beforeKey = processing ? "current_processing_rate_pct" : unitPrice ? "current_unit_price" : unitCost ? "current_unit_cost" : "current_amount"; const afterKey = processing ? "proposed_processing_rate_pct" : unitPrice ? "proposed_unit_price" : unitCost ? "proposed_unit_cost" : "proposed_amount"; return <tr key={row.id} className={row.excluded || row.duplicate_of ? styles.excluded : undefined}>
          <td><WrappedCell label="Action name" value={row.label ?? ""} disabled={disabled || row.excluded} placeholder="Describe the change" onChange={(text) => changeAction(row.id, { label: text })} />{row.explanation ? <p className={styles.cellExplanation}>{row.explanation}</p> : null}</td>
          <td><select aria-label={`Change type for ${row.label || "action"}`} value={row.kind ?? "expense_reduction"} disabled={disabled || row.excluded || Boolean(row.expense_row_id) && !["expense_reduction", "expense_increase"].includes(row.kind ?? "")} onChange={(event) => changeAction(row.id, { kind: event.target.value as OperatingAction["kind"] })}>{OPERATING_ACTIONS.filter(([key]) => !row.expense_row_id || !["expense_reduction", "expense_increase"].includes(row.kind ?? "") || ["expense_reduction", "expense_increase"].includes(key)).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></td>
          <td>{row.kind === "unit_volume" ? <button type="button" className={styles.link} onClick={focusUnits}>Edit unit plan above</button> : row.cost_basis === "per_unit" && ["expense_reduction", "expense_increase"].includes(row.kind ?? "") ? <><strong>{money(operatingExpenseAmount(row))}</strong><small>{display(row.current_units_per_period) || "?"} {row.unit_label || "units"} per period</small></> : number(`Current ${processing ? "rate percent" : unitPrice || unitCost ? "unit amount" : "amount"} for ${row.label || "action"}`, row[beforeKey], (text) => changeAction(row.id, { [beforeKey]: text }), Boolean(row.expense_row_id))}</td>
          <td>{row.kind === "unit_volume" ? <button type="button" className={styles.link} onClick={focusUnits}>Edit unit plan above</button> : row.cost_basis === "per_unit" && ["expense_reduction", "expense_increase"].includes(row.kind ?? "") ? <><strong>{money(operatingExpenseAmount(row, true))}</strong><button type="button" className={styles.link} onClick={() => setSelected(row.expense_row_id ? { collection: "expenses", id: row.expense_row_id } : { collection: "adjustments", id: row.id })}>Edit unit costs</button></> : number(`Proposed ${processing ? "rate percent" : unitPrice || unitCost ? "unit amount" : "amount"} for ${row.label || "action"}`, row[afterKey], (text) => changeAction(row.id, { [afterKey]: text }))}</td>
          <td>{row.kind === "unit_volume" ? "Year" : row.expense_row_id ? <span>{OPERATING_CADENCES.find(([key]) => key === row.cadence)?.[1] ?? "Month"}</span> : cadence(`Frequency for ${row.label || "action"}`, row.cadence, (text) => changeAction(row.id, { cadence: text }))}</td>
          <td className={styles.amount}>{money(result ? result.net_annual_impact : illustrativeActionImpact(row))}{row.cadence === "one_time" ? <small>One time</small> : null}</td>
          <td>{evidenceLinks(row.source_file_ids)}</td><td><span>{operatingLabel(result?.review_state ?? row.status ?? "proposed")}</span>{result?.issues?.length ? <button type="button" className={styles.link} onClick={() => setSelected({ collection: "adjustments", id: row.id })}>{result.issues.length} to resolve</button> : null}</td><td>{rowTools("adjustments", row)}</td>
        </tr>; })}{!active(actions).length ? <tr><td colSpan={9} className={styles.empty}>No earnings actions proposed. Current earnings remain unchanged.</td></tr> : null}</tbody>
        <tfoot><tr><th>Projected earnings changes</th><td colSpan={3}>Proposed: {money(evaluation?.totals.proposed.annual_impact)} / year</td><td colSpan={3}>Reviewed: {money(evaluation?.totals.approved.annual_impact)} / year</td><td colSpan={2}>Historical results preserved</td></tr></tfoot>
      </table></div>
      {reviewControls}
    </> : <OperatingPlanImpact evaluation={evaluation} evaluating={evaluating} currency={currency} client={!staff} />}
    {focusedExpense ? <section className={styles.details} aria-label="Expense details"><div className={styles.toolbar}><h4>{focusedExpense.label || "Expense details"}</h4><button type="button" onClick={() => setSelected(null)}>Close details</button></div><OperatingVolumeBehavior row={focusedExpense} missing={unitEvaluation?.rows.find(item => item.id === focusedExpense.id)?.missing} disabled={disabled} onChange={patch => changeExpense(focusedExpense.id, patch)} /><div className={styles.fields}>
      <label>Cost basis<select aria-label="Expense cost basis" value={focusedExpense.cost_basis ?? "total"} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { cost_basis: event.target.value as OperatingCostBasis })}><option value="total">Period total</option><option value="per_unit">Quantity × unit cost + fixed</option></select></label>
      {focusedExpense.cost_basis === "per_unit" ? <>
        <label>Unit name<input aria-label="Expense unit name" placeholder="Unit, seat, employee, campaign, transaction…" value={focusedExpense.unit_label ?? ""} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { unit_label: event.target.value })} /></label>
        <label>Frequency{cadence("Expense unit period", focusedExpense.cadence, (text) => changeExpense(focusedExpense.id, { cadence: text }))}</label>
        <label>Current quantity per period{number("Current expense quantity", focusedExpense.current_units_per_period, (text) => changeExpense(focusedExpense.id, { current_units_per_period: text }))}</label>
        <label>Current cost per unit{number("Current expense unit cost", focusedExpense.current_unit_cost, (text) => changeExpense(focusedExpense.id, { current_unit_cost: text }))}</label>
        <label>Current fixed cost per period{number("Current expense fixed cost", focusedExpense.current_fixed_amount, (text) => changeExpense(focusedExpense.id, { current_fixed_amount: text }))}<small>Enter 0 when there is no fixed cost. Blank stays unknown.</small></label>
        <label>Proposed quantity per period{number("Proposed expense quantity", focusedExpenseAction?.proposed_units_per_period, (text) => onChange(proposeExpenseUnits(value, focusedExpense.id, { proposed_units_per_period: text }, uid)))}</label>
        <label>Proposed cost per unit{number("Proposed expense unit cost", focusedExpenseAction?.proposed_unit_cost, (text) => onChange(proposeExpenseUnits(value, focusedExpense.id, { proposed_unit_cost: text }, uid)))}</label>
        <label>Proposed fixed cost per period{number("Proposed expense fixed cost", focusedExpenseAction?.proposed_fixed_amount, (text) => onChange(proposeExpenseUnits(value, focusedExpense.id, { proposed_fixed_amount: text }, uid)))}</label>
        <div className={`${styles.unitComparison} ${styles.wide}`}><span>Current period cost <strong>{money(operatingExpenseAmount(focusedExpense))}</strong></span><span>Proposed period cost <strong>{focusedExpenseAction ? money(operatingExpenseAmount(focusedExpenseAction, true)) : "—"}</strong></span><span>Quantity × unit cost + fixed cost</span></div>
        <label className={styles.wide}>Reported source total · reference only{number("Reported expense source total", focusedExpense.current_amount, (text) => changeExpense(focusedExpense.id, { current_amount: text }))}<small>The source total is retained for reconciliation and is not added to the unit calculation. Reconcile the unit inputs with this total before review; notes alone do not resolve a mismatch. Correct the source reference only if it is inaccurate. Proposed changes still need evidence, timing and staff review.</small></label>
      </> : null}
      <label>Payee<input value={focusedExpense.payee ?? ""} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { payee: event.target.value })} /></label>
      <label className={styles.check}><input type="checkbox" checked={focusedExpense.essential ?? false} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { essential: event.target.checked })} />Essential to operations</label>
      <label>Duplicate of<select value={focusedExpense.duplicate_of ?? ""} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { duplicate_of: event.target.value || null, excluded: Boolean(event.target.value) })}><option value="">Separate expense</option>{expenses.filter((row) => row.id !== focusedExpense.id && !row.excluded && !row.duplicate_of).map((row) => <option key={row.id} value={row.id}>{row.label || "Unnamed expense"}</option>)}</select></label>
      <label className={styles.wide}>Notes<textarea value={focusedExpense.notes ?? ""} disabled={disabled} onChange={(event) => changeExpense(focusedExpense.id, { notes: event.target.value })} /></label>{filePicker(focusedExpense, (ids) => changeExpense(focusedExpense.id, { source_file_ids: ids }))}
    </div></section> : null}
    {focusedAction ? <section className={styles.details} aria-label="Earnings action details"><div className={styles.toolbar}><h4>{focusedAction.label || "Action details"}</h4><button type="button" onClick={() => setSelected(null)}>Close details</button></div><div className={styles.fields}>
      {["expense_reduction", "expense_increase", "processing_cost_change", "marketing_investment"].includes(focusedAction.kind ?? "") ? <label className={styles.wide}>Linked expense<select aria-label="Linked expense for action" value={focusedAction.expense_row_id ?? ""} disabled={disabled} onChange={(event) => onChange(linkOperatingActionExpense(value, focusedAction.id, event.target.value || null))}><option value="">Separate disclosed assumption</option>{expenses.filter((row) => !row.excluded && !row.duplicate_of).map((row) => <option key={row.id} value={row.id}>{row.label || "Unnamed expense"}</option>)}</select><small>Link a cost already in the table to use its current amount, units, period and evidence. Proposed changes stay intact; the source values still require reconciliation.</small></label> : null}
      {focusedAction.kind === "unit_volume" ? <p><button type="button" onClick={focusUnits}>Edit unit plan above</button> · Annual volume illustration; overall projection and review checks remain authoritative.{focusedAction.cadence !== "annual" ? <button type="button" disabled={disabled} onClick={() => changeAction(focusedAction.id, { cadence: "annual" })}>Use annual frequency</button> : null}</p> : null}<label>Product or service<input maxLength={160} value={focusedAction.product_name ?? ""} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { product_name: event.target.value })} /></label>{focusedAction.kind === "marketing_investment" ? <label>Revenue per $1 of additional marketing spend (assumption){number("Marketing revenue return multiple", focusedAction.revenue_return_multiple, (text) => changeAction(focusedAction.id, { revenue_return_multiple: text }))}</label> : null}<label>Product / cost identity<input value={focusedAction.driver_key ?? ""} disabled={disabled || Boolean(focusedAction.expense_row_id) && focusedAction.kind !== "marketing_investment"} placeholder="Use the same identity for linked price and cost changes" onChange={(event) => changeAction(focusedAction.id, { driver_key: event.target.value })} /></label>
      {["expense_reduction", "expense_increase"].includes(focusedAction.kind ?? "") && !focusedAction.expense_row_id ? <>
        <label>Cost basis<select aria-label="Action cost basis" value={focusedAction.cost_basis ?? "total"} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { cost_basis: event.target.value as OperatingCostBasis, ...(event.target.value === "per_unit" ? { current_amount: null, proposed_amount: null } : {}) })}><option value="total">Period total</option><option value="per_unit">Quantity × unit cost + fixed</option></select></label>
        {focusedAction.cost_basis === "per_unit" ? <><label>Unit name<input aria-label="Action unit name" value={focusedAction.unit_label ?? ""} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { unit_label: event.target.value })} /></label>{([["current_units_per_period", "Current quantity per period"], ["current_unit_cost", "Current cost per unit"], ["current_fixed_amount", "Current fixed cost per period"], ["proposed_units_per_period", "Proposed quantity per period"], ["proposed_unit_cost", "Proposed cost per unit"], ["proposed_fixed_amount", "Proposed fixed cost per period"]] as const).map(([key, label]) => <label key={key}>{label}{number(`Action ${label.toLowerCase()}`, focusedAction[key], (text) => changeAction(focusedAction.id, { [key]: text }))}</label>)}<p className={`${styles.muted} ${styles.wide}`}>Blank costs are unknown. Enter 0 explicitly when no fixed fee applies. Retained period totals must reconcile with quantity × unit cost + fixed cost.</p></> : null}
      </> : null}
<label>Effective date<input type="date" value={focusedAction.effective_date ?? ""} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { effective_date: event.target.value })} /></label>
      {focusedAction.kind === "price_change" || focusedAction.kind === "product_cost_change" ? <label>Units per period{number("Units per period", focusedAction.units_per_period, (text) => changeAction(focusedAction.id, { units_per_period: text }))}</label> : null}
      {focusedAction.kind === "revenue_change" || focusedAction.kind === "marketing_investment" ? <label>Contribution margin, %{number("Contribution margin percent", focusedAction.contribution_margin_pct, (text) => changeAction(focusedAction.id, { contribution_margin_pct: text }))}</label> : null}
      {focusedAction.kind === "processing_cost_change" ? <>
        {processingReferences && onProcessingReference ? <><label>Current processing statement<select aria-label="Current processing statement" value={focusedAction.merchant_source_key ?? ""} disabled={disabled} onChange={(event) => onProcessingReference(focusedAction, event.target.value, focusedAction.merchant_offer_id ?? "")}><option value="">Choose current statement</option>{processingReferences.sources.map((source) => <option key={source.key} value={source.key}>{source.label}</option>)}</select></label><label>Proposed processing quote<select aria-label="Proposed processing quote" value={focusedAction.merchant_offer_id ?? ""} disabled={disabled || !focusedAction.merchant_source_key} onChange={(event) => onProcessingReference(focusedAction, focusedAction.merchant_source_key ?? "", event.target.value)}><option value="">Choose proposed quote</option>{processingReferences.offers.map((offer) => <option key={offer.id} value={offer.id}>{offer.label}</option>)}</select></label></> : null}
        <label>Card volume per period{number("Card volume per period", focusedAction.processing_volume, (text) => changeAction(focusedAction.id, { processing_volume: text }))}</label><label>Transactions per period{number("Transactions per period", focusedAction.processing_transaction_count, (text) => changeAction(focusedAction.id, { processing_transaction_count: text }))}</label>{(["current", "proposed"] as const).map((prefix) => <div className={styles.processing} key={prefix}><h5>{prefix === "current" ? "Current statement" : "Proposed quote"}</h5><label>Rate basis<select aria-label={`${prefix} processing rate basis`} value={focusedAction[`${prefix}_processing_rate_basis`] ?? "unknown"} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { [`${prefix}_processing_rate_basis`]: event.target.value })}><option value="unknown">Unconfirmed</option><option value="all_in">All-in effective rate</option><option value="processor_markup">Processor markup only</option></select></label>{focusedAction[`${prefix}_processing_rate_basis`] === "processor_markup" ? <><label>Fixed fee per period{number(`${prefix} processing fixed fee`, focusedAction[`${prefix}_processing_fixed_fee`], (text) => changeAction(focusedAction.id, { [`${prefix}_processing_fixed_fee`]: text }))}</label><label>Fee per transaction{number(`${prefix} per transaction fee`, focusedAction[`${prefix}_processing_per_transaction_fee`], (text) => changeAction(focusedAction.id, { [`${prefix}_processing_per_transaction_fee`]: text }))}</label></> : <small>All-in rate already includes fixed and transaction fees.</small>}</div>)}
      </> : null}
      <label>Implementation / transition cost{number("Implementation cost", focusedAction.implementation_cost, (text) => changeAction(focusedAction.id, { implementation_cost: text }))}</label><label>Implementation cost timing<select value={focusedAction.implementation_cost_cadence ?? "one_time"} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { implementation_cost_cadence: event.target.value as OperatingAction["implementation_cost_cadence"] })}><option value="one_time">One time</option><option value="monthly">Monthly</option><option value="annual">Annual</option></select></label>
      <label>Duplicate of<select value={focusedAction.duplicate_of ?? ""} disabled={disabled} onChange={(event) => changeAction(focusedAction.id, { duplicate_of: event.target.value || null, excluded: Boolean(event.target.value) })}><option value="">Separate action</option>{actions.filter((row) => row.id !== focusedAction.id && !row.excluded && !row.duplicate_of).map((row) => <option key={row.id} value={row.id}>{row.label || "Unnamed action"}</option>)}</select></label>
      <label className={styles.wide}>Explanation for the financial package<textarea value={focusedAction.explanation ?? ""} disabled={disabled} placeholder="What will change, why it is achievable, and how it affects earnings" onChange={(event) => changeAction(focusedAction.id, { explanation: event.target.value })} /></label>
      <label className={styles.wide}>Evidence / assumptions<textarea value={focusedAction.source_note ?? ""} disabled={disabled} placeholder="Current source, proposed quote and assumptions to verify" onChange={(event) => changeAction(focusedAction.id, { source_note: event.target.value })} /></label>{filePicker(focusedAction, (ids) => changeAction(focusedAction.id, { source_file_ids: ids }))}
    </div>{([...(actionResult(focusedAction)?.issues ?? []), ...(actionResult(focusedAction)?.risk_flags ?? [])]).length ? <ul className={styles.issues}>{[...(actionResult(focusedAction)?.issues ?? []), ...(actionResult(focusedAction)?.risk_flags ?? [])].map((issue, index) => <li key={`${index}:${issue}`}>{issue}</li>)}</ul> : null}</section> : null}
    <label className={styles.notes}>Plan notes<textarea value={value.notes ?? ""} disabled={disabled} onChange={(event) => change({ notes: event.target.value })} /></label>
    <p className={styles.muted}>Proposals are separate from historical financial results. Your team reviews evidence and reconciles the baseline before using a change in an underwriting projection.</p>
    </details>
  </div>;
}

export function OperatingPlanImpact({ evaluation, evaluating, currency, client }: { evaluation?: OperatingEvaluation | null; evaluating?: boolean; currency: string; client?: boolean }) {
  if (!evaluation) return <div className={styles.empty}>{evaluating ? "Calculating the working plan…" : client ? "Your team will review your proposed changes and their effect on earnings after you save this form." : "Add operating expenses and earnings actions to compare the accepted baseline with proposed and reviewed results."}</div>;
  const money = (v: number | null | undefined) => operatingMoney(v, evaluation.baseline.currency ?? currency); const ratio = (v: number | null | undefined) => v == null ? "—" : `${v.toFixed(2)}x`;
  const before = evaluation.baseline; const proposed = evaluation.projection.proposed; const approved = evaluation.projection.approved;
  const noiMoney = (amount: number | null | undefined) => metricAmountLabel(amount, before.noi_governance ? before.noi_governance.currency : before.currency ?? currency);
  const rows = [["Annual earnings / EBITDA", money(before.earnings), money(proposed.earnings), money(approved.earnings)], ["First-year earnings · after timing and implementation", money(before.earnings), money(proposed.first_year_earnings), money(approved.first_year_earnings)], ["Annual NOI", noiMoney(before.noi), noiMoney(proposed.noi), noiMoney(approved.noi)], ["First-year DSCR · current debt", ratio(before.dscr), ratio(proposed.first_year_dscr_current), ratio(approved.first_year_dscr_current)], ["First-year DSCR · with refinance", "—", ratio(proposed.first_year_dscr_with_refinance), ratio(approved.first_year_dscr_with_refinance)], ["Stabilized run-rate DSCR · current debt", ratio(before.dscr), ratio(proposed.dscr_current), ratio(approved.dscr_current)], ["Stabilized run-rate DSCR · with refinance", "—", ratio(proposed.dscr_with_refinance), ratio(approved.dscr_with_refinance)], ["Earnings gap to 1.25x · current debt", "—", money(proposed.target_gap_current), money(approved.target_gap_current)], ["Earnings gap to 1.25x · refinance", "—", money(proposed.target_gap_refinance), money(approved.target_gap_refinance)], ["Annual earnings change", "—", money(evaluation.totals.proposed.annual_impact), money(evaluation.totals.approved.annual_impact)], ["First-year change · after one-time costs", "—", money(evaluation.totals.proposed.first_year_impact), money(evaluation.totals.approved.first_year_impact)]];
  return <section>{before.noi_governance ? <NoiGovernanceSummary baseline={before.noi_governance} /> : null}<p className={styles.muted}>{evaluating ? "Updating preview… · " : ""}Baseline: {before.period || "Period unconfirmed"} · {before.earnings_kind ? operatingLabel(before.earnings_kind) : "Earnings source needed"}{before.provisional ? " · provisional" : ""}. Proposed results are conditional; reviewed results use reconciled actions.</p><div className={styles.scroll}><table><thead><tr><th>Metric</th><th>Current baseline</th><th>All proposed · illustration</th><th>Staff reviewed · projection</th></tr></thead><tbody>{rows.map(([label, current, proposedValue, reviewed]) => <tr key={label}><th>{label}</th><td className={styles.amount}>{current}</td><td className={styles.amount}>{proposedValue}</td><td className={styles.amount}>{reviewed}</td></tr>)}</tbody></table></div>{[...(evaluation.missing ?? []), ...(evaluation.risk_flags ?? [])].length ? <div className={styles.details}><h4>Still needed / review notes</h4><ul>{[...(evaluation.missing ?? []), ...(evaluation.risk_flags ?? [])].map((item, index) => <li key={`${index}:${item}`}>{item}</li>)}</ul></div> : null}<p className={styles.muted}>Refinancing changes debt service. Interest, principal and loan proceeds do not change operating earnings by themselves. Projections do not establish program qualification.</p></section>;
}
